        .reorder(j, ri)      // inner: j, outer: ri  => for (ri) for (j)
        .vectorize(j, vec);  // j is inner and contiguous in memory for A_param(j, ri)

    // ---- Schedule for q_func: q[i] = sum_j A[i][j] * p[j] ----
    //
    // Here A_param(rj, i) reads rows of A (rj is dim 0), which are already
    // contiguous. The default loop order for the update is:
    //
    //   for (i) for (rj) ...
    //
    // which already has rj innermost and contiguous. We:
    //   - parallelize across i (independent outputs),
    //   - vectorize across rj inside the reduction.
    q_func.compute_root();
    q_func.vectorize(i, vec).parallel(i);

    q_func.update()
        .vectorize(rj, vec)  // contiguous along rj (dim 0 of A_param and p_param)
        .parallel(i);        // independent reductions for each i

    // JIT-compile both functions once with the chosen target, so timing
    // below measures only execution, not compilation.
    s_func.compile_jit(target);
    q_func.compile_jit(target);

    // Measure execution time of the "kernel" (computing both s and q).
    auto start = std::chrono::high_resolution_clock::now();

    s_func.realize(s);
    q_func.realize(q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results, similar to print_array in the C version.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print s (length m), newline every 20 elements.
        std::cerr << "s:";
        for (int idx = 0; idx < m; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << s(idx) << ' ';
        }
        std::cerr << "\nq:";

        // Print q (length n), newline every 20 elements.
        for (int idx = 0; idx < n; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << q(idx) << ' ';
        }
        std::cerr << '\n';
    }

    // Print elapsed time in seconds (like gemm.cpp).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
