              .split(j, jo, ji, tile_j)
              // We want the loop order: jo (outer, parallel),
              // ri (rows), ji (inner, contiguous j).
              // reorder() lists vars from innermost to outermost.
              .reorder(ji, ri, jo)
              // Vectorize along ji (unit-stride in A's j-dimension).
              .vectorize(ji, vec_width)
              // Parallelize across tiles of j. Different jo tiles
              // update disjoint ranges of s[j], so this is safe.
              .parallel(jo);
