        // As with s, the pure step (zeroing q) is cheap; we keep it
        // simple and focus optimization on the reduction.
        q_func.compute_root();

        q_func.update()
              // Tile i: i = io * tile_i + ii.
              .split(i, io, ii, tile_i)
              // Pure Vars io, ii are outer, RDom rj is innermost
              // by default, which is what we want for vectorizing rj.
              // Parallelize across tiles in i.
              .parallel(io)
              // Vectorize along the unit-stride reduction dim rj.
              .vectorize(rj, vec_width);
