    //   p[i] = (DATA_TYPE)(i % m) / m;
    //   r[i] = (DATA_TYPE)(i % n) / n;
    Expr inv_m = cast<num_t>(1) / cast<int>(m);
    Expr inv_n = cast<num_t>(1) / cast<int>(n);

    // p[i] = (DATA_TYPE)(i % m) / m;
    init_p(i) = cast<num_t>(i % m) * inv_m;

    // r[i] = (DATA_TYPE)(i % n) / n;
    init_r(i) = cast<num_t>(i % n) * inv_n;

    // A[i][j] = (DATA_TYPE)(i * (j+1) % n) / n;
