    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // 1D vectors p and r.
    init_p.compute_root()
          .vectorize(i, vec_width)
          .parallel(i);

    init_r.compute_root()
          .vectorize(i, vec_width)
          .parallel(i);

    // 2D matrix A(j, i) with j (dim 0) contiguous, parallelize over i (rows).
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec_width);

